import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
    open: true,
  },
});

export interface StoredData {
  duration: number;
  todayCount: number;
  todayDate: string;
}

const STORAGE_KEY = 'sit-reminder';

const defaultData: StoredData = {
  duration: 45 * 60,
  todayCount: 0,
  todayDate: new Date().toDateString(),
};

function getToday(): string {
  return new Date().toDateString();
}

export function loadData(): StoredData {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...defaultData };
    const data: StoredData = JSON.parse(raw);
    if (data.todayDate !== getToday()) {
      return { duration: data.duration, todayCount: 0, todayDate: getToday() };
    }
    return data;
  } catch {
    return { ...defaultData };
  }
}

export function saveData(data: StoredData): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

export function incrementCount(): StoredData {
  const data = loadData();
  if (data.todayDate !== getToday()) {
    data.todayCount = 1;
    data.todayDate = getToday();
  } else {
    data.todayCount += 1;
  }
  saveData(data);
  return data;
}

export function saveDuration(duration: number): StoredData {
  const data = loadData();
  data.duration = duration;
  saveData(data);
  return data;
}

import { useState, useRef, useCallback, useEffect } from 'react';

export type TimerStatus = 'idle' | 'running' | 'paused' | 'resting';

interface UseTimerOptions {
  initialDuration: number;
  restDuration?: number;
  onWorkComplete?: () => void;
  onRestComplete?: () => void;
  onTick?: (timeLeft: number, status: TimerStatus) => void;
}

interface UseTimerReturn {
  timeLeft: number;
  totalDuration: number;
  status: TimerStatus;
  isRunning: boolean;
  start: () => void;
  pause: () => void;
  reset: (newDuration?: number) => void;
  skip: () => void;
}

export function useTimer({
  initialDuration,
  restDuration = 5 * 60,
  onWorkComplete,
  onRestComplete,
  onTick,
}: UseTimerOptions): UseTimerReturn {
  const [totalDuration, setTotalDuration] = useState(initialDuration);
  const [timeLeft, setTimeLeft] = useState(initialDuration);
  const [status, setStatus] = useState<TimerStatus>('idle');
  const intervalRef = useRef<number | null>(null);

  const clearIntervalRef = useCallback(() => {
    if (intervalRef.current !== null) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  const stopTimer = useCallback(() => {
    clearIntervalRef();
  }, [clearIntervalRef]);

  const tick = useCallback(() => {
    setTimeLeft((prev) => {
      const next = prev - 1;
      if (next <= 0) {
        stopTimer();
        return 0;
      }
      return next;
    });
  }, [stopTimer]);

  // Notify parent of ticks
  useEffect(() => {
    onTick?.(timeLeft, status);
  }, [timeLeft, status, onTick]);

  // Handle completion
  useEffect(() => {
    if (timeLeft === 0 && status === 'running') {
      onWorkComplete?.();
      // Start rest mode
      setStatus('resting');
      setTimeLeft(restDuration);
      setTotalDuration(restDuration);
    }
    if (timeLeft === 0 && status === 'resting') {
      onRestComplete?.();
      setStatus('idle');
      setTimeLeft(initialDuration);
      setTotalDuration(initialDuration);
    }
  }, [timeLeft, status, restDuration, initialDuration, onWorkComplete, onRestComplete]);

  const start = useCallback(() => {
    clearIntervalRef();
    setStatus((prev) => {
      if (prev === 'paused' || prev === 'idle') {
        intervalRef.current = window.setInterval(tick, 1000);
        return prev === 'idle' && timeLeft === totalDuration ? 'running' : 'running';
      }
      return prev;
    });
    if (status === 'idle') {
      intervalRef.current = window.setInterval(tick, 1000);
    } else if (status === 'paused') {
      intervalRef.current = window.setInterval(tick, 1000);
    }
  }, [clearIntervalRef, tick, status, timeLeft, totalDuration]);

  // Re-build start to avoid status dependency issues
  const startTimer = useCallback(() => {
    stopTimer();
    if (timeLeft <= 0) return;
    intervalRef.current = window.setInterval(tick, 1000);
    setStatus((s) => (s === 'resting' ? 'resting' : 'running'));
  }, [stopTimer, tick, timeLeft]);

  const pause = useCallback(() => {
    stopTimer();
    setStatus('paused');
  }, [stopTimer]);

  const reset = useCallback(
    (newDuration?: number) => {
      stopTimer();
      const dur = newDuration ?? initialDuration;
      setTotalDuration(dur);
      setTimeLeft(dur);
      setStatus('idle');
    },
    [stopTimer, initialDuration]
  );

  const skip = useCallback(() => {
    stopTimer();
    if (status === 'running') {
      setTimeLeft(0);
    } else if (status === 'resting') {
      setTimeLeft(0);
    }
  }, [stopTimer, status]);

  // Sync initialDuration changes
  useEffect(() => {
    if (status === 'idle') {
      setTimeLeft(initialDuration);
      setTotalDuration(initialDuration);
    }
  }, [initialDuration, status]);

  return {
    timeLeft,
    totalDuration,
    status,
    isRunning: status === 'running' || status === 'resting',
    start: startTimer,
    pause,
    reset,
    skip,
  };
}

import { useCallback, useRef } from 'react';

export function useNotification() {
  const permissionRef = useRef<NotificationPermission>('default');

  const requestPermission = useCallback(async (): Promise<boolean> => {
    if (!('Notification' in window)) return false;
    if (Notification.permission === 'granted') {
      permissionRef.current = 'granted';
      return true;
    }
    const result = await Notification.requestPermission();
    permissionRef.current = result;
    return result === 'granted';
  }, []);

  const notify = useCallback(
    (title: string, body: string, icon?: string) => {
      if (!('Notification' in window)) return;
      if (Notification.permission === 'granted') {
        new Notification(title, { body, icon, tag: 'sit-reminder' });
      } else if (Notification.permission === 'default') {
        requestPermission().then((granted) => {
          if (granted) {
            new Notification(title, { body, icon, tag: 'sit-reminder' });
          }
        });
      }
    },
    [requestPermission]
  );

  return { notify, requestPermission };
}

import { memo } from 'react';
import styles from './TimerCircle.module.css';

interface TimerCircleProps {
  timeLeft: number;
  totalDuration: number;
  label: string;
  size?: number;
  strokeWidth?: number;
}

function formatTime(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

export const TimerCircle = memo(function TimerCircle({
  timeLeft,
  totalDuration,
  label,
  size = 260,
  strokeWidth = 8,
}: TimerCircleProps) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const progress = totalDuration > 0 ? timeLeft / totalDuration : 0;
  const dashOffset = circumference * (1 - progress);
  const center = size / 2;

  return (
    <div className={styles.wrapper} style={{ width: size, height: size }}>
      <svg
        className={styles.svg}
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        role="timer"
        aria-label={`${label}: ${formatTime(timeLeft)}`}
      >
        {/* Background circle */}
        <circle
          className={styles.track}
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          strokeWidth={strokeWidth}
        />
        {/* Progress circle */}
        <circle
          className={styles.progress}
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={dashOffset}
          strokeLinecap="round"
          transform={`rotate(-90 ${center} ${center})`}
          style={{
            transition: 'stroke-dashoffset 1s linear',
          }}
        />
      </svg>
      <div className={styles.content}>
        <span className={styles.time}>{formatTime(timeLeft)}</span>
        <span className={styles.label}>{label}</span>
      </div>
    </div>
  );
});

